-- Resoluciones ampliadas de los integradores 6.14–6.17.
-- IMPORTANTE: esta migración no modifica statement_html; las consignas permanecen textuales.
begin;

update public.exercise_solutions s set solution_html=$cbc$<div class="solutionStep"><span>Paso 1</span><div><h4>Separar polaridad de enlace y polaridad molecular</h4><p>En <strong>CO₂</strong> cada enlace C=O es polar porque O es más electronegativo que C. Por lo tanto, la opción a) no puede justificarse diciendo que “no tiene enlaces polares”.</p></div></div><div class="solutionStep"><span>Paso 2</span><div><h4>Analizar CO₂ con la geometría dada</h4><p>CO₂ es <strong>lineal</strong>. Los dos dipolos C=O tienen igual módulo y apuntan en sentidos opuestos a 180°. Por simetría se cancelan y el momento dipolar molecular resulta <strong>μtotal = 0</strong>. La molécula es apolar aunque sus enlaces sean polares.</p></div></div><div class="solutionStep"><span>Paso 3</span><div><h4>Analizar SO₂</h4><p>SO₂ es <strong>angular</strong>. Los dos vectores de enlace no están enfrentados a 180°, por lo que no pueden cancelarse completamente. Queda un <strong>momento dipolar neto distinto de cero</strong> y la molécula es polar.</p></div></div><div class="solutionStep"><span>Paso 4</span><div><h4>Revisar las interacciones</h4><p>Todas las moléculas presentan <strong>London</strong>. Además, como SO₂ es polar, entre sus moléculas hay <strong>dipolo–dipolo</strong>. Por eso b) es falsa. Tampoco es correcta c): no hay fundamento para afirmar que London sea mayor en CO₂; SO₂ tiene más electrones y es más polarizable.</p></div></div><div class="solutionStep"><span>Paso 5</span><div><h4>Elegir la opción</h4><p>La afirmación correcta es <strong>d) el SO₂ es más polar que el CO₂</strong>, porque SO₂ posee dipolo molecular neto y CO₂ no.</p></div></div><div class="solutionStep verification"><span>Control</span><div><h4>Qué había que justificar</h4><p><strong>Enlaces polares + geometría + suma vectorial</strong>. Ésa es la cadena que permite decidir la polaridad molecular.</p></div></div>$cbc$, final_answer=$cbc$<p><strong>d)</strong> SO₂ es más polar que CO₂. CO₂ es lineal y sus dipolos se cancelan; SO₂ es angular y conserva un dipolo molecular neto.</p>$cbc$,student_visible=true,updated_at=now() from public.exercises e where s.exercise_id=e.id and e.subject='chemistry' and e.unit_no=4 and e.title='Ejercicio 6.14 (Integrador)';

update public.exercise_solutions s set solution_html=$cbc$<div class="solutionStep"><span>Paso 1</span><div><h4>Identificar los elementos a partir de Z</h4><p><strong>Z = 20 → Ca</strong>, <strong>Z = 34 → Se</strong>, <strong>Z = 35 → Br</strong> y <strong>Z = 55 → Cs</strong>.</p></div></div><div class="solutionStep"><span>Paso 2</span><div><h4>Calcular el número de oxidación de X en XO₂⁻</h4><p>Tomando O con NOX −2, la suma debe ser igual a la carga del ion:</p><p><strong>x + 2(−2) = −1</strong></p><p><strong>x − 4 = −1</strong></p><p><strong>x = +3</strong></p><p>Entre las opciones dadas, el anión habitual con esa fórmula es <strong>BrO₂⁻</strong>, llamado <strong>bromito</strong>. Por lo tanto, X es Br, Z = 35.</p></div></div><div class="solutionStep"><span>Paso 3</span><div><h4>Formular la oxosal de magnesio</h4><p>El magnesio forma <strong>Mg²⁺</strong> y el bromito es <strong>BrO₂⁻</strong>. Se necesitan dos aniones por cada catión para neutralizar la carga:</p><p><strong>Mg²⁺ + 2 BrO₂⁻ → Mg(BrO₂)₂</strong></p><p>Nombre: <strong>bromito de magnesio</strong>.</p></div></div><div class="solutionStep"><span>Paso 4</span><div><h4>Contar electrones de valencia de BrO₂⁻</h4><p>Br aporta 7 e⁻, los dos O aportan 12 e⁻ y la carga −1 agrega 1 e⁻:</p><p><strong>7 + 2·6 + 1 = 20 e⁻</strong></p><p>La estructura de Lewis se representa mediante formas resonantes O=Br—O⁻ ↔ ⁻O—Br=O. Sobre Br quedan <strong>dos pares libres</strong>.</p></div></div><div class="solutionStep"><span>Paso 5</span><div><h4>Aplicar TRePEV</h4><p>Alrededor de Br hay <strong>4 dominios</strong>: dos dominios enlazantes y dos pares libres. La notación es <strong>AX₂E₂</strong>. La geometría electrónica es tetraédrica y la <strong>geometría molecular es angular</strong>.</p></div></div><div class="solutionStep"><span>Paso 6</span><div><h4>Ángulo aproximado</h4><p>El ángulo tetraédrico ideal es 109,5°, pero los pares libres repelen más que los pares enlazantes. Por eso el ángulo O—Br—O se espera <strong>menor que 109,5°</strong>. TRePEV permite justificar la disminución sin exigir un valor experimental exacto.</p></div></div><div class="solutionStep verification"><span>Control</span><div><h4>Chequeo final</h4><p>Carga de la sal: +2 + 2(−1) = 0. En BrO₂⁻: 20 electrones de valencia y AX₂E₂, por lo que la forma es angular.</p></div></div>$cbc$, final_answer=$cbc$<p><strong>a)</strong> X = Br (Z = 35); anión BrO₂⁻, bromito; oxosal: Mg(BrO₂)₂, bromito de magnesio. <strong>b)</strong> AX₂E₂, geometría molecular angular y ángulo O—Br—O menor que 109,5°.</p>$cbc$,student_visible=true,updated_at=now() from public.exercises e where s.exercise_id=e.id and e.subject='chemistry' and e.unit_no=4 and e.title='Ejercicio 6.15 (Integrador)';

update public.exercise_solutions s set solution_html=$cbc$<div class="solutionStep"><span>Paso 1</span><div><h4>Usar la cantidad total de protones</h4><p>Cada átomo de F tiene <strong>Z = 9</strong>, por lo tanto aporta 9 protones. Los tres F aportan:</p><p><strong>3·9 = 27 protones</strong></p></div></div><div class="solutionStep"><span>Paso 2</span><div><h4>Encontrar Z de X</h4><p>La molécula XF₃ tiene 32 protones en total:</p><p><strong>Z(X) + 27 = 32</strong></p><p><strong>Z(X) = 5</strong></p><p>El elemento con Z = 5 es <strong>boro, B</strong>. La especie es BF₃.</p></div></div><div class="solutionStep"><span>Paso 3</span><div><h4>Escribir la configuración electrónica externa</h4><p>Para B: 1s² 2s² 2p¹. Por lo tanto, su <strong>CEE es 2s² 2p¹</strong>.</p></div></div><div class="solutionStep"><span>Paso 4</span><div><h4>Determinar la geometría de BF₃</h4><p>En Lewis, B queda unido a tres F y no posee pares libres sobre el centro. Hay <strong>3 dominios</strong>: AX₃. Según TRePEV la geometría es <strong>triangular plana</strong>, con ángulos cercanos a 120°.</p></div></div><div class="solutionStep"><span>Paso 5</span><div><h4>Decidir la polaridad molecular</h4><p>Cada enlace B—F es polar, pero los tres dipolos están distribuidos simétricamente a 120°. La suma vectorial es cero, por lo que <strong>BF₃ es apolar</strong>.</p></div></div><div class="solutionStep"><span>Paso 6</span><div><h4>Identificar las interacciones en el líquido</h4><p>Al ser una molécula apolar, no presenta dipolo–dipolo permanente ni puente de hidrógeno. Entre moléculas de BF₃ actúan <strong>fuerzas de dispersión de London</strong>.</p></div></div><div class="solutionStep verification"><span>Control</span><div><h4>Cadena de resolución</h4><p>Protones → elemento → CEE → Lewis/TRePEV → simetría → polaridad → fuerza intermolecular.</p></div></div>$cbc$,final_answer=$cbc$<p><strong>a)</strong> X = B. <strong>b)</strong> CEE = 2s² 2p¹. <strong>c)</strong> BF₃ es trigonal plano y apolar; en el líquido predominan interacciones de London.</p>$cbc$,student_visible=true,updated_at=now() from public.exercises e where s.exercise_id=e.id and e.subject='chemistry' and e.unit_no=4 and e.title='Ejercicio 6.16 (Integrador)';

update public.exercise_solutions s set solution_html=$cbc$<div class="solutionStep"><span>Paso 1</span><div><h4>Identificar T</h4><p>Un átomo neutro de T tiene 6 electrones, por lo tanto tiene 6 protones y <strong>Z(T) = 6</strong>. T es <strong>carbono, C</strong>.</p></div></div><div class="solutionStep"><span>Paso 2</span><div><h4>Encontrar X usando los protones totales</h4><p>La molécula TX₂ posee 22 protones:</p><p><strong>6 + 2·Z(X) = 22</strong></p><p><strong>2·Z(X) = 16</strong></p><p><strong>Z(X) = 8</strong></p><p>El elemento con Z = 8 es <strong>oxígeno, O</strong>. Entonces TX₂ = CO₂.</p></div></div><div class="solutionStep"><span>Paso 3</span><div><h4>Analizar los enlaces</h4><p>O es más electronegativo que C, por lo que cada enlace C=O es <strong>covalente polar</strong>. Los dipolos individuales apuntan desde C hacia cada O.</p></div></div><div class="solutionStep"><span>Paso 4</span><div><h4>Determinar la geometría</h4><p>La Lewis es O=C=O. Sobre el C central hay <strong>2 dominios electrónicos</strong> y ningún par libre: AX₂. Según TRePEV la molécula es <strong>lineal</strong>, con un ángulo O—C—O de 180°.</p></div></div><div class="solutionStep"><span>Paso 5</span><div><h4>Sumar los dipolos</h4><p>Los dos dipolos tienen igual módulo y sentidos opuestos. Por la simetría lineal:</p><p><strong>μtotal = μ₁ + μ₂ = 0</strong></p><p>Por lo tanto, <strong>CO₂ es una molécula apolar</strong>, aunque cada enlace C=O sea polar.</p></div></div><div class="solutionStep verification"><span>Control</span><div><h4>Error que había que evitar</h4><p>No confundir <strong>enlace polar</strong> con <strong>molécula polar</strong>. La geometría decide si los vectores se cancelan.</p></div></div>$cbc$,final_answer=$cbc$<p>TX₂ es <strong>CO₂</strong>. Sus enlaces C=O son polares, pero la geometría es lineal y simétrica; los dipolos se cancelan y la molécula es <strong>apolar</strong>.</p>$cbc$,student_visible=true,updated_at=now() from public.exercises e where s.exercise_id=e.id and e.subject='chemistry' and e.unit_no=4 and e.title='Ejercicio 6.17 (Integrador)';

-- Garantiza que las 39 resoluciones existentes de U3/U4 permanezcan visibles.
update public.exercise_solutions s set student_visible=true,updated_at=now() from public.exercises e where s.exercise_id=e.id and e.subject='chemistry' and e.unit_no in (3,4);

commit;
